  const date = new Date(dateString);

  return new Intl.DateTimeFormat('en-US', {
    month: 'numeric',
    day: 'numeric',
    year: 'numeric'
  }).format(date);
};

function tryFormatDate(span) {
  const rawDate = span.textContent.trim();
  const formatted = formatSurveyDate(rawDate);
  if (formatted) {
    span.textContent = formatted;
    return true;
  }
  return false;
}

function waitForDateAndFormat() {
  const endsAt = document.getElementById("user_endsAt");

  const maxAttempts = 20;
  let attempts = 0;

  const interval = setInterval(() => {
    if (!endsAt) return clearInterval(interval);

    const ok1 = tryFormatDate(endsAt);

    attempts++;
    if (ok1 || attempts >= maxAttempts) {
      clearInterval(interval);
    }
  }, 200);
}

setTimeout(waitForDateAndFormat, 0);

const applyStyles = (selector, styles) => {
  const elements = document.querySelectorAll(selector);
