  width: 392px;
  padding: 0;
}

.rfmodal-header-mobileweb h3 {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.rfmodal-header-mobileweb .rf-header {
  text-align: center;
  padding: 0 30px;
}

.rfmodal-message-mobileweb {
  text-align: center;
  padding: 0 16px;
  line-height: 18px;
}

.rfmodal-footer-mobileweb > div:first-child {
  display: flex;
  padding: 0 30px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-direction: row-reverse;
}

.rfmodal-footer-mobileweb .rfmodal-button-yes.primary-btn-p {
  width: 172px !important;
  border: 1px solid  #004FFF;
  background-color: transparent !important;
  color: #004FFF !important;
}

.rfmodal-footer-mobileweb .rfmodal-button-yes.secondary-btn-p {
  margin: 0 !important;
  width: 172px !important;
  background-color: rgb(0, 79, 255) !important;
}

.mobilewebModalContentWrapper .rfmodal-close {
  right: -18px;
}
.mobilewebModalContentWrapper #rfmodal-close-icon {
  right: -18px;
  fill: transparent!important;
}

.mobilewebModalContentWrapper .modal-privacy-tos.modal-terms-long-type {
  padding: 56px 0 0 !important;
}

.rfmodal-body-mobileweb {
  padding-bottom: 10px;
}

.div--750px .modal-privacy-tos {
  left: 24px;
  bottom: 24px;
}

.rfmodal-message-mobileweb .top-img {
  position: absolute;
  top: 0px;
  left: 0px;
}

.rfmodal-footer .secondary-btn-p {
  display: none;
}

.rfmodal-footer-mobileweb button {
  font-size: 14px !important;
  border-radius: 4px;
  padding: 10px 0px !important;
}

.mobilewebModalContentWrapper .modal-privacy-tos {
  display: none;
}
